import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const png = readFileSync(join(root, "public", "logo-white.png"));
const outDir = join(root, "lib", "assets");
mkdirSync(outDir, { recursive: true });
const outFile = join(outDir, "logo-white-data-url.ts");
const body =
  "// Auto-generated by scripts/embed-logo-data-url.mjs — do not edit by hand.\n" +
  "export const LOGO_WHITE_PNG_DATA_URL =\n" +
  `  "data:image/png;base64,${png.toString("base64")}";\n`;
writeFileSync(outFile, body);
console.log(`wrote ${outFile} (${body.length} bytes)`);
